fn is_decimal_with_two_precision(s: &[u8]) -> bool {
    // We need at least 3 characters for there to be a '.' followed by exactly two characters.
    if s.len() < 3 {
        return false;
    }
    // Check if the byte at position len - 3 is '.'
    s[s.len() - 3] == b'.'
}

